    /**
     * Method to retrieve the Opportunity via OpportunityFetchOneSummary
     * @param 	summary OpportunityFetchOneSummary 
     * @return 	OpportunityFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Opportunity getOpportunity( OpportunityFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "OpportunityFetchOneSummary arg cannot be null" );
    	
    	Opportunity entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Opportunity
        	// --------------------------------------
        	CompletableFuture<Opportunity> futureEntity = queryGateway.query(new FindOpportunityQuery( new LoadOpportunityFilter( summary.getOpportunityId() ) ), ResponseTypes.instanceOf(Opportunity.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Opportunity with id " + summary.getOpportunityId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


