	/**
	 * Internal helper method to load the root 
	 * 
	 * @param		id	UUID
	 * @return		Opportunity
	 */
	protected Opportunity load( UUID id ) throws ProcessingException {
		opportunity = OpportunityService.getOpportunityInstance().getOpportunity( new OpportunityFetchOneSummary(id) );	
		return opportunity;
	}


